# 推斷：資料表=上月名冊、本月名冊（表頭第1列）｜欄位=員工編號、姓名、時數、部門、職稱｜主檔=員工編號｜鍵=員工編號｜篩選=有變更的欄位｜輸出=新工作表「變更明細」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_old = wb['上月名冊']
ws_new = wb['本月名冊']

# 讀取表頭
headers = [cell.value for cell in ws_old[1]]
emp_idx = headers.index('員工編號')
compare_fields = [h for h in headers if h != '員工編號']

# 建立舊資料字典
old_data = {}
for row in ws_old.iter_rows(min_row=2, values_only=True):
    emp_id = row[emp_idx]
    old_data[emp_id] = {field: row[i] for i, field in enumerate(headers) if field != '員工編號'}

# 建立新資料字典
new_data = {}
for row in ws_new.iter_rows(min_row=2, values_only=True):
    emp_id = row[emp_idx]
    new_data[emp_id] = {field: row[i] for i, field in enumerate(headers) if field != '員工編號'}

# 建立輸出工作表
if '變更明細' in wb.sheetnames:
    del wb['變更明細']
ws_out = wb.create_sheet('變更明細')
ws_out.append(['員工編號', '變更欄位', '舊值', '新值'])

# 比較共同員工的每個欄位
for emp_id in old_data:
    if emp_id in new_data:
        for field in compare_fields:
            old_val = old_data[emp_id].get(field)
            new_val = new_data[emp_id].get(field)
            if old_val != new_val:
                ws_out.append([emp_id, field, old_val, new_val])

wb.save(OUTPUT_PATH)
