# 推斷：資料表=上月名冊、本月名冊（表頭第1列）｜欄位=姓名、時數、部門、職稱｜主檔=上月名冊｜鍵=員工編號｜篩選=共同員工且欄位值不同｜輸出=新工作表「變更」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
last_month = wb['上月名冊']
this_month = wb['本月名冊']

# 建立上月資料字典
last_data = {}
for row in last_month.iter_rows(min_row=2, values_only=True):
    emp_id = row[0]
    last_data[emp_id] = {
        '姓名': row[1],
        '時數': row[2],
        '部門': row[3],
        '職稱': row[4]
    }

# 建立本月資料字典
this_data = {}
for row in this_month.iter_rows(min_row=2, values_only=True):
    emp_id = row[0]
    this_data[emp_id] = {
        '姓名': row[1],
        '時數': row[2],
        '部門': row[3],
        '職稱': row[4]
    }

# 找出變更
