# 推斷：資料表=上月名冊、本月名冊（表頭第1列）｜欄位=姓名、時數、部門、職稱｜主檔=員工編號｜鍵=員工編號｜篩選=兩表共同員工的欄位值差異｜輸出=新工作表「變更清單」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_prev = wb['上月名冊']
ws_curr = wb['本月名冊']

# 讀取欄位名稱（跳過員工編號列，即第2列到最後一列）
field_names = []
for col_idx in range(2, ws_prev.max_column + 1):
    field_names.append(ws_prev.cell(row=1, column=col_idx).value)

# 建立上月資料字典：員工編號 -> {欄位名: 值}
prev_data = {}
for row in ws_prev.iter_rows(min_row=2, values_only=True):
    emp_id = row[0]
    if emp_id is None:
        continue
    prev_data[emp_id] = {field_names[i]: row[i+1] for i in range(len(field_names))}

# 建立本月資料字典
curr_data = {}
for row in ws_curr.iter_rows(min_row=2, values_only=True):
    emp_id = row[0]
    if emp_id is None:
        continue
    curr_data[emp_id] = {field_names[i]: row[i+1] for i in range(len(field_names))}

# 比較共同員工的每個欄位，收集變更
changes = []
for emp_id, prev_fields in prev_data.items():
    if emp_id in curr_data:
        curr_fields = curr_data[emp_id]
        for field in field_names:
            old_val = prev_fields.get(field)
            new_val = curr_fields.get(field)
            if old_val != new_val:
                changes.append((emp_id, field, old_val, new_val))

# 建立新工作表（若已存在則先刪除）
if '變更清單' in wb.sheetnames:
    del wb['變更清單']
ws_new = wb.create_sheet('變更清單')

# 寫入表頭與資料
ws_new.append(['員工編號', '變更欄位', '舊值', '新值'])
for change in changes:
    ws_new.append(change)

# 儲存
wb.save(OUTPUT_PATH)
