# 推斷：資料表=系統帳與實盤（表頭第1列）｜欄位=料號、品名、數量｜主檔=系統帳｜鍵=料號｜篩選=數量不同｜輸出=新工作表「差異比對」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_sys = wb['系統帳']
ws_real = wb['實盤']

# 建立系統帳資料字典：料號 -> (品名, 數量)
sys_data = {}
for row in ws_sys.iter_rows(min_row=2, values_only=True):
    if row[0] is not None and str(row[0]).strip() != '' and str(row[0]).strip() != '小計':
        sys_data[row[0]] = (row[1], row[2])

# 建立實盤資料字典：料號 -> 數量
real_data = {}
