        real_data[row[0]] = row[2]

# 找出數量不同的料號
diff_items = []
for key in sys_data:
    if key in real_data:
        old_qty = sys_data[key][1]
        new_qty = real_data[key]
        if old_qty != new_qty:
            diff_items.append((key, sys_data[key][0], old_qty, new_qty))

