```python
# 推斷：資料表=系統帳與實盤（表頭第1列）｜欄位=料號、品名、數量｜主檔=系統帳｜鍵=料號｜篩選=數量有變動（小計列與說明列排除）｜輸出=新工作表「數量變動」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws_sys = wb['系統帳']
ws_act = wb['實盤']

# 建立系統帳字典：料號 -> (品名, 數量)
sys_dict = {}
for row in ws_sys.iter_rows(min_row=2, values_only=True):
    part_no = row[0]
    if part_no is None or str(part_no).strip() == '':
        continue
    # 跳過小計和說明列：品名可能為「小計」或包含「（」
    if row[1] and ('小計' in str(row[1]) or '（' in str(row[1])):
        continue
    sys_dict[part_no] = (row[1], row[2])

# 建立實盤字典：料號 -> 數量
act_dict = {}
for row in ws_act.iter_rows(min_row=2, values_only=True):
    part_no = row[0]
    if part_no is None or str(part_no).strip() == '':
        continue
    if row[1] and ('小計' in str(row[1]) or '（' in str(row[1])):
        continue
    act_dict[part_no] = row[2]

# 找出數量有變動的料號
diff_rows = []
for part_no, (name, old_qty) in sys_dict.items():
    if part_no in act_dict:
        new_qty = act_dict[part_no]
        if old_qty != new_qty:
            diff_rows.append((part_no, name, old_qty, new_qty))

# 建立新工作表
if '數量變動' in wb.sheetnames:
    del wb['數量變動']
ws_new = wb.create_sheet('數量變動')
ws_new.append(['料號', '品名', '舊數量', '新數量'])
for row in diff_rows:
    ws_new.append(row)

wb.save(OUTPUT_PATH)
